import{_ as o,o as t,c as r,ax as s}from"./chunks/framework.D0-oyZN4.js";const p=JSON.parse('{"title":"Troubleshooting","description":"Every documented Developer Studio CLI error message, what it means, and how to recover.","frontmatter":{"description":"Every documented Developer Studio CLI error message, what it means, and how to recover."},"headers":[],"relativePath":"cli/reference/troubleshooting.md","filePath":"cli/reference/troubleshooting.md"}'),i={name:"cli/reference/troubleshooting.md"};function a(n,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/reference/troubleshooting.md for this page in Markdown format</div><h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Reference of the error messages <code>gsds</code> prints and the state each one describes.</p><h2 id="directory-path-is-not-empty" tabindex="-1"><code>Directory &quot;&lt;path&gt;&quot; is not empty</code> <a class="header-anchor" href="#directory-path-is-not-empty" aria-label="Permalink to &quot;`Directory &quot;&lt;path&gt;&quot; is not empty`&quot;">​</a></h2><p><code>gsds init</code> didn&#39;t recognize the target directory as an existing widget project — none of <code>extensions_registry.json</code>, <code>connectors_registry.json</code>, <code>gsds.json</code>, or the legacy <code>widget_registry.json</code> are present — and it isn&#39;t empty.</p><p><strong>Recover:</strong> If the directory already has project files that should have matched one of the names above (perhaps under a slightly different name), fix that first. Otherwise, if you&#39;re sure the directory is safe to scaffold into, re-run with <code>--force</code>. See <a href="./commands.html#gsds-init"><code>gsds init</code></a> for the full list of what&#39;s recognized without it.</p><h2 id="no-gsds-json-found" tabindex="-1"><code>no gsds.json found</code> <a class="header-anchor" href="#no-gsds-json-found" aria-label="Permalink to &quot;`no gsds.json found`&quot;">​</a></h2><p><code>gsds</code> is running outside a project. Every command except <code>gsds init</code> requires a <code>gsds.json</code> marker in the current directory or an ancestor.</p><p><strong>Recover:</strong> <code>cd</code> into your project root, or scaffold a new project with <code>gsds init &lt;name&gt;</code>.</p><h2 id="session-is-invalid-or-expired" tabindex="-1"><code>session is invalid or expired</code> <a class="header-anchor" href="#session-is-invalid-or-expired" aria-label="Permalink to &quot;`session is invalid or expired`&quot;">​</a></h2><p>The stored session token failed against your tenant. Session tokens are valid for 8 hours and cannot be refreshed. Affects <code>gsds preview</code> and <code>gsds connector test</code>.</p><p><strong>Recover:</strong> Get a fresh pairing code from <strong>Integrations → Developer Studio → CLI Access</strong> in your community and redeem it with <code>gsds login &lt;pairing_code&gt;</code>. Confirm with <code>gsds login --status</code>.</p><h2 id="stored-login-has-expired-run-gsds-login-pairing-code-to-re-authenticate" tabindex="-1"><code>Stored login has expired. Run gsds login &lt;pairing_code&gt; to re-authenticate.</code> <a class="header-anchor" href="#stored-login-has-expired-run-gsds-login-pairing-code-to-re-authenticate" aria-label="Permalink to &quot;`Stored login has expired. Run gsds login &lt;pairing_code&gt; to re-authenticate.`&quot;">​</a></h2><p><code>gsds preview</code> found a stored session for the profile, but it has timed out. This is distinct from <code>Run gsds login &lt;pairing_code&gt; first.</code>, which means nothing is stored for that profile at all.</p><p><strong>Recover:</strong> Redeem a fresh pairing code under the same profile. <code>gsds profile</code> marks an expired profile <code>(expired)</code>, and one whose stored credential cannot be read <code>(unreadable)</code>, so you can see which one to log back into.</p><h2 id="a-profile-is-marked-unreadable" tabindex="-1">A profile is marked <code>(unreadable)</code> <a class="header-anchor" href="#a-profile-is-marked-unreadable" aria-label="Permalink to &quot;A profile is marked `(unreadable)`&quot;">​</a></h2><p><code>gsds profile</code> lists the profile, but its stored credential cannot be read back — the entry exists and its contents are corrupted, hand-edited, or restored from a backup that no longer parses. It is not a usable session, and it is reported separately from <code>(expired)</code> because nothing about it can be read, including whether it had timed out.</p><p><strong>Recover:</strong> Same as an expired session — redeem a fresh pairing code under that profile with <code>gsds login &lt;pairing_code&gt; --profile &lt;name&gt;</code>.</p><h2 id="pairing-code-expired" tabindex="-1">Pairing code expired <a class="header-anchor" href="#pairing-code-expired" aria-label="Permalink to &quot;Pairing code expired&quot;">​</a></h2><p>Pairing codes have a 1-minute time-to-live.</p><p><strong>Recover:</strong> Get a fresh pairing code from <strong>CLI Access</strong> and redeem it immediately, with your terminal already open.</p><h2 id="a-registry-file-is-missing" tabindex="-1">A registry file is missing <a class="header-anchor" href="#a-registry-file-is-missing" aria-label="Permalink to &quot;A registry file is missing&quot;">​</a></h2><p><code>extensions_registry.json</code> or <code>connectors_registry.json</code> is gone from a project that previously had it. <code>gsds build</code> refuses rather than writing an empty registry: the file is the source of truth, not generated output, so rebuilding cannot recover the titles, categories, configuration, and types it held.</p><p><strong>Recover:</strong> Restore the file from version control. To deliberately start over, create it yourself with an empty <code>{&quot;widgets&quot;: []}</code> (or <code>{&quot;connectors&quot;: []}</code>).</p><h2 id="missing-required-field-category" tabindex="-1"><code>Missing required field: category</code> <a class="header-anchor" href="#missing-required-field-category" aria-label="Permalink to &quot;`Missing required field: category`&quot;">​</a></h2><p>A widget entry in <code>extensions_registry.json</code> is missing a required field. <code>gsds build</code> refuses to write the registry until every entry declares a non-empty <code>title</code> and <code>category</code>.</p><p><strong>Recover:</strong> Add a <code>category</code> string to the entry named in the error.</p><h2 id="script-x-points-at-missing-file" tabindex="-1"><code>Script &quot;x&quot; points at missing file</code> <a class="header-anchor" href="#script-x-points-at-missing-file" aria-label="Permalink to &quot;`Script &quot;x&quot; points at missing file`&quot;">​</a></h2><p>An <code>extensions_registry.json</code> entry references a file that no longer exists in the project. <code>gsds build</code> refuses to write the registry while it is inconsistent.</p><p><strong>Recover:</strong> Either restore the missing file, or remove the stale entry with <code>gsds script rm &lt;name&gt;</code> or <code>gsds style rm &lt;name&gt;</code>. <code>gsds create</code> warns on the same drift without failing, so you can scaffold new widgets while cleaning up.</p><h2 id="widget-json-ignored-no-longer-used-safe-to-delete" tabindex="-1"><code>widget.json ignored, no longer used, safe to delete</code> <a class="header-anchor" href="#widget-json-ignored-no-longer-used-safe-to-delete" aria-label="Permalink to &quot;`widget.json ignored, no longer used, safe to delete`&quot;">​</a></h2><p>A leftover <code>widget.json</code> or <code>connectors.json</code> inside a widget directory. Both registries are the sole source of truth now, and <code>gsds build</code> never reads either file.</p><p><strong>Recover:</strong> Delete the file. This message only appears when the widget already has an entry in <code>extensions_registry.json</code>, so nothing is lost with it.</p><h2 id="widget-json-found-but-not-in-extensions-registry-json" tabindex="-1"><code>widget.json found but not in extensions_registry.json</code> <a class="header-anchor" href="#widget-json-found-but-not-in-extensions-registry-json" aria-label="Permalink to &quot;`widget.json found but not in extensions_registry.json`&quot;">​</a></h2><p>The same leftover file, for a widget with no registry entry. Here the file is the widget&#39;s only remaining metadata, so deleting it loses the widget.</p><p><strong>Recover:</strong> Copy the widget&#39;s <code>title</code>, <code>category</code>, <code>type</code>, and <code>source</code> or <code>content</code> into an <code>extensions_registry.json</code> entry, then delete the file.</p><h2 id="widgets-name-has-no-entry-in-extensions-registry-json" tabindex="-1"><code>widgets/&lt;name&gt;/ has no entry in extensions_registry.json</code> <a class="header-anchor" href="#widgets-name-has-no-entry-in-extensions-registry-json" aria-label="Permalink to &quot;`widgets/&lt;name&gt;/ has no entry in extensions_registry.json`&quot;">​</a></h2><p>A widget directory the registry never mentions. The platform only serves what the registry declares, so this widget will never appear in your community.</p><p><strong>Recover:</strong> Add an entry for it to <code>extensions_registry.json</code>, or delete the folder if it is not a widget.</p><h2 id="version-mismatch-across-widgets" tabindex="-1"><code>version mismatch across widgets</code> <a class="header-anchor" href="#version-mismatch-across-widgets" aria-label="Permalink to &quot;`version mismatch across widgets`&quot;">​</a></h2><p>Two widgets declare the same dependency in <code>package.json</code> but resolve it to different installed versions. <code>gsds build</code> externalizes a shared dependency into one import map entry, so it cannot serve two versions at once.</p><p><strong>Recover:</strong> The error names each widget and version. Align the versions, or remove the dependency from one widget, then re-run <code>gsds build</code>. See <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a>.</p><h2 id="excluded-from-shared-dependency-deduplication" tabindex="-1"><code>excluded from shared-dependency deduplication</code> <a class="header-anchor" href="#excluded-from-shared-dependency-deduplication" aria-label="Permalink to &quot;`excluded from shared-dependency deduplication`&quot;">​</a></h2><p>A widget&#39;s <code>vite.config.ts</code> (or <code>angular.json</code>) couldn&#39;t be auto-migrated to the externalized-dependency shape. This only happens once the widget actually shares a dependency with another widget, and its build file has a shape <code>gsds build</code> can&#39;t confidently patch — a custom <code>rollupOptions</code>, or a build block laid out differently than the standard template.</p><p><strong>Recover:</strong> Copy the <code>externalPackages</code> block from a freshly scaffolded widget&#39;s <code>vite.config.ts</code> into the named widget&#39;s file. See <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a>.</p><h2 id="payload-rejected" tabindex="-1"><code>--payload</code> rejected <a class="header-anchor" href="#payload-rejected" aria-label="Permalink to &quot;`--payload` rejected&quot;">​</a></h2><p><code>--payload</code> accepts a file reference only. Inline JSON, and files that do not contain valid JSON, are rejected.</p><p><strong>Recover:</strong> Put the payload in a file and pass it as <code>--payload @body.json</code>. Confirm the file parses as JSON.</p><h2 id="port-in-use" tabindex="-1">Port in use <a class="header-anchor" href="#port-in-use" aria-label="Permalink to &quot;Port in use&quot;">​</a></h2><p><code>gsds preview</code> failed to bind its port. The default is <code>5173</code>.</p><p><strong>Recover:</strong> <code>gsds preview --port &lt;port&gt;</code> on a free port.</p><h2 id="the-browser-blocks-the-local-preview" tabindex="-1">The browser blocks the local preview <a class="header-anchor" href="#the-browser-blocks-the-local-preview" aria-label="Permalink to &quot;The browser blocks the local preview&quot;">​</a></h2><p><code>gsds preview</code> serves from <code>http://localhost:5173</code> by default, and each JavaScript widget&#39;s own <code>dev</code> script serves from a further port. Your community page — served over HTTPS — loads from those addresses directly. Chrome 142 and later treat that as a local network request and ask permission the first time, with a prompt about looking for and connecting to devices on your local network. Other Chromium-based browsers behave the same way. Granting it once covers every port your preview uses.</p><p><strong>Recover:</strong> Choose <strong>Allow</strong> when the prompt appears. If you already chose to block it, reopen the choice from the site settings icon at the left of the address bar and allow local network access for your community&#39;s address, then reload the page. Until it is allowed, the browser cannot reach your local server and your local widgets do not load.</p><h2 id="widget-missing-from-the-picker" tabindex="-1">Widget missing from the picker <a class="header-anchor" href="#widget-missing-from-the-picker" aria-label="Permalink to &quot;Widget missing from the picker&quot;">​</a></h2><p><code>gsds preview</code> is running but a widget does not appear in the No-Code Builder.</p><p><strong>Recover:</strong> Check three things, in order.</p><ol><li><strong>The widget has a registry entry.</strong> <code>gsds build</code> never derives entries from a folder scan, so a <code>widgets/&lt;name&gt;/</code> folder the registry doesn&#39;t declare is invisible.</li><li><strong>The widget declares a <code>dev</code> script</strong> in its <code>package.json</code>, or its registry entry declares a <code>source</code> so the preview server can serve it directly. A widget with neither is skipped, and <code>gsds preview</code> says so.</li><li><strong>You are signed in to the community as the same account that ran <code>gsds login</code>.</strong> The No-Code Builder looks for a preview session belonging to the account you are signed in as, so a session paired under a different account is not visible to you. Confirm the paired account with <code>gsds login --status</code>.</li></ol><h2 id="a-preview-asset-404s-or-loads-the-wrong-file" tabindex="-1">A preview asset 404s or loads the wrong file <a class="header-anchor" href="#a-preview-asset-404s-or-loads-the-wrong-file" aria-label="Permalink to &quot;A preview asset 404s or loads the wrong file&quot;">​</a></h2><p>A widget served as static HTML references an asset that does not load under <code>gsds preview</code>.</p><p><strong>Recover:</strong> Resolve references the way publishing does. A reference that starts with a slash — a root-absolute reference, such as <code>/app.js</code> — resolves against the widget root, <code>widgets/&lt;name&gt;/app.js</code>, not against the directory its HTML sits in. A reference naming no file in the widget is left exactly as written and warned about once, so check that warning for a typo before assuming the server is at fault.</p><h2 id="per-widget-build-failed" tabindex="-1"><code>Per-widget build failed</code> <a class="header-anchor" href="#per-widget-build-failed" aria-label="Permalink to &quot;`Per-widget build failed`&quot;">​</a></h2><p>One or more widgets could not be prepared, and <code>gsds build</code> names each one. The most common cause is a dependency install that failed: <code>gsds build</code> installs each widget&#39;s dependencies automatically, leaves a widget whose install failed out of the rebuild pass, and then fails the whole run rather than shipping a stale <code>dist/</code> for it. The widget&#39;s registry entry is untouched — the registry is hand-authored, and no build path removes an entry.</p><p><strong>Recover:</strong> Run <code>npm install</code> (or your package manager&#39;s equivalent) inside the named widget&#39;s directory to see the underlying error. Fix it, then re-run <code>gsds build</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Session model → <a href="./../authenticate.html">Authenticate</a></li><li>Where <code>.gsds/</code> and the keychain fit in → <a href="./project-files.html">Project files</a></li><li>Flags for each command → <a href="./commands.html">Command reference</a></li><li>Shared dependency deduplication → <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a></li></ul>',66)])])}const u=o(i,[["render",a]]);export{p as __pageData,u as default};
